fn set_operations() {
    println!("\n=== 集合操作 ===");

    let set_a = BTreeSet::from([1, 2, 3, 4, 5]);
    let set_b = BTreeSet::from([4, 5, 6, 7, 8]);

    println!("集合 A: {:?}", set_a);
    println!("集合 B: {:?}", set_b);

    // 并集 - 所有出现在 A 或 B 中的元素
    let union: BTreeSet&lt;_&gt; = set_a.union(&amp;set_b).cloned().collect();
    println!("并集 A ∪ B: {:?}", union); // {1, 2, 3, 4, 5, 6, 7, 8}

    // 交集 - 同时出现在 A 和 B 中的元素
    let intersection: BTreeSet&lt;_&gt; = set_a.intersection(&amp;set_b).cloned().collect();
    println!("交集 A ∩ B: {:?}", intersection); // {4, 5}

    // 差集 - 在 A 中但不在 B 中的元素
    let difference: BTreeSet&lt;_&gt; = set_a.difference(&amp;set_b).cloned().collect();
    println!("差集 A - B: {:?}", difference); // {1, 2, 3}

    // 对称差集 - 在 A 或 B 中但不同时在两者的元素
    let symmetric_difference: BTreeSet&lt;_&gt; = set_a.symmetric_difference(&amp;set_b).cloned().collect();
    println!("对称差集 A Δ B: {:?}", symmetric_difference); // {1, 2, 3, 6, 7, 8}
}

