    println!("集合 B: {:?}", set_b);
    println!("集合 C: {:?}", set_c);

    // 子集判断
    println!("A 是 B 的子集: {}", set_a.is_subset(&amp;set_b));    // true
    println!("B 是 A 的子集: {}", set_b.is_subset(&amp;set_a));    // false

    // 超集判断
    println!("B 是 A 的超集: {}", set_b.is_superset(&amp;set_a));  // true
    println!("A 是 B 的超集: {}", set_a.is_superset(&amp;set_b));  // false

    // 不相交判断
    println!("A 和 C 不相交: {}", set_a.is_disjoint(&amp;set_c));  // true
    println!("B 和 C 不相交: {}", set_b.is_disjoint(&amp;set_c));  // false
}
