    }
}

fn main() {
    let name = "Alice";
    let age = 30;

    // 基本格式化
    let s = format!("{} is {} years old", name, age);
    println!("{}", s);

    // 位置参数
    let s = format!("{0} is {1} years old. {0} likes coding.", name, age);
    println!("{}", s);

    // 命名参数
    let s = format!("{name} is {age} years old", name = name, age = age);
    println!("{}", s);

    // 格式化数字
    println!("二进制: {:b}", 42);
    println!("十六进制: {:x}", 42);
    println!("八进制: {:o}", 42);
    println!("科学计数法: {:e}", 42.0);

    // 对齐和填充
    println!("'{:&gt;10}'", "right");     // 右对齐
    println!("'{:&lt;10}'", "left");     // 左对齐
    println!("'{:^10}'", "center");   // 居中
    println!("'{:0&gt;5}'", "42");       // 前导零填充

    // 调试格式化
    println!("{:?}", vec![1, 2, 3]);
    println!("{:#?}", vec![1, 2, 3]);  // 多行格式

    // 自定义类型格式化
    let p = Point { x: 3.0, y: 4.0 };
    println!("Point: {}", p);
}
