库名 核心特点 易用性 适用场景 Authlib 支持 OIDC 服务端实现，内置 JWT 签发 / 验证，兼容标准 ⭐⭐⭐⭐ 自建轻量 OIDC 服务 python-oidc 纯 OIDC 服务端实现，遵循 OpenID Connect Core 规范 ⭐⭐⭐ 标准化 OIDC 服务端 Keycloak Admin Client Keycloak 客户端，通过 Keycloak 提供 OIDC 服务（零代码自研） ⭐⭐⭐⭐⭐ 企业级 IAM 场景 <p>🌟 推荐：Python 中无需写代码实现 OIDC 服务端，优先用 Keycloak（部署后通过控制台配置即可），或 Django OAuth Toolkit（Django 生态，开箱即用）。</p> <p>示例（Authlib + Flask 构建轻量 OIDC 授权服务端）：</p> <pre><code>from flask import Flask, request, jsonify
from authlib.integrations.flask_oauth2 import AuthorizationServer
from authlib.oauth2.rfc6749.grants import AuthorizationCodeGrant
from authlib.oidc.core.grants import OpenIDCode
from authlib.jose import JsonWebKey

app = Flask(__name__)
app.secret_key = "YOUR_APP_SECRET"


# --- 需自行实现：从数据库查询客户端、持久化 Token ---
def query_client(client_id):
    # 返回实现 OAuth2ClientMixin 接口的对象
    return ClientModel.query.filter_by(client_id=client_id).first()

def save_token(token, request):
    tok = TokenModel(user_id=request.user.id, **token)
    db.session.add(tok); db.session.commit()


authorization = AuthorizationServer(app, query_client=query_client, save_token=save_token)


# --- OIDC 扩展：定义 ID Token 内容 ---
class MyOpenIDCode(OpenIDCode):
    def exists_nonce(self, nonce, request):
        # 防重放：检查 nonce 是否已使用
        return NonceModel.query.filter_by(value=nonce).first() is not None

    def get_jwt_config(self, grant):
        with open("private_key.pem") as f:
            private_key = JsonWebKey.import_key(f.read())
        return {"key": private_key, "alg": "RS256",
                "iss": "http://localhost:5000", "exp": 3600}

    def generate_user_info(self, user, scope):
        data = {"sub": str(user.id)}
        if "email" in scope:
            data.update({"email": user.email, "email_verified": user.email_verified})
        if "profile" in scope:
            data["name"] = user.name
        return data


# 注册授权码 Grant + OIDC 扩展
authorization.register_grant(AuthorizationCodeGrant, [MyOpenIDCode()])


# --- 标准 OIDC 端点 ---
@app.route("/oauth/authorize", methods=["GET", "POST"])
def authorize():
    return authorization.create_authorization_response()

@app.route("/oauth/token", methods=["POST"])
def issue_token():
    return authorization.create_token_response()

# JWKS 端点（供 RP 验证 ID Token 签名）
@app.route("/.well-known/jwks.json")
def jwks():
    with open("public_key.pem") as f:
        key = JsonWebKey.import_key(f.read())
    return jsonify({"keys": [key.as_dict()]})

# Discovery 端点（RP 自动发现配置）
@app.route("/.well-known/openid-configuration")
def openid_config():
    base = "http://localhost:5000"
    return jsonify({
        "issuer": base,
        "authorization_endpoint": f"{base}/oauth/authorize",
        "token_endpoint": f"{base}/oauth/token",
        "jwks_uri": f"{base}/.well-known/jwks.json",
        "response_types_supported": ["code"],
        "subject_types_supported": ["public"],
        "id_token_signing_alg_values_supported": ["RS256"],
        "scopes_supported": ["openid", "email", "profile"],
    })
</code></pre>

库名 核心特点 易用性 适用场景 ory/hydra 工业级 OIDC/OAuth2 服务端，开源、可扩展、符合标准，无需自研代码 ⭐⭐⭐⭐⭐ 企业级身份认证 go-oidc/oidc OIDC 核心实现，可基于此构建服务端，轻量灵活 ⭐⭐⭐ 自定义 OIDC 服务端 keycloak-client-go Keycloak 客户端，通过 Keycloak 提供 OIDC 服务（零代码自研） ⭐⭐⭐⭐⭐ 快速搭建 IAM 系统 <p>🌟 推荐：Go 中无需写代码实现 OIDC 服务端，优先用 Ory Hydra（开箱即用，支持分布式部署）或 Keycloak（可视化配置）。</p> <p>示例（Ory Hydra Login Provider — Go 应用对接 Hydra Admin API）：</p> <pre><code>// Hydra 以独立服务部署（docker run ory/hydra）。
// Go 应用实现"登录提供商"（Login Provider）：当用户登录时，
// Hydra 将请求重定向到该应用验证身份，应用通过 Admin API 通知 Hydra 接受/拒绝。
package main

import (
    "context"
    "fmt"
    "net/http"

    hydra "github.com/ory/hydra-client-go/v2"
)

func main() {
    // 配置 Hydra Admin API 客户端（仅内网可达，不暴露公网）
    cfg := hydra.NewConfiguration()
    cfg.Servers = []hydra.ServerConfiguration{{URL: "http://localhost:4445"}}
    adminAPI := hydra.NewAPIClient(cfg)

    // Hydra 将浏览器重定向到 /login?login_challenge=xxx
    http.HandleFunc("/login", func(w http.ResponseWriter, r *http.Request) {
        challenge := r.URL.Query().Get("login_challenge")

        // 1. 查询本次登录请求的上下文
        loginReq, _, err := adminAPI.OAuth2API.
            GetOAuth2LoginRequest(context.Background()).
            LoginChallenge(challenge).Execute()
        if err != nil {
            http.Error(w, err.Error(), http.StatusInternalServerError)
            return
        }

        // 2. 已有会话则直接接受（免二次登录）
        if loginReq.GetSkip() {
            resp, _, _ := adminAPI.OAuth2API.
                AcceptOAuth2LoginRequest(context.Background()).
                LoginChallenge(challenge).
                AcceptOAuth2LoginRequest(hydra.AcceptOAuth2LoginRequest{
                    Subject: loginReq.GetSubject(),
                }).Execute()
            http.Redirect(w, r, resp.GetRedirectTo(), http.StatusFound)
            return
        }

        // 3. 展示登录表单
        fmt.Fprintf(w, `&lt;form method="POST" action="/login/submit?login_challenge=%s"&gt;
            用户名: &lt;input name="username"&gt; 密码: &lt;input name="password" type="password"&gt;
            &lt;button&gt;登录&lt;/button&gt;&lt;/form&gt;`, challenge)
    })

    http.HandleFunc("/login/submit", func(w http.ResponseWriter, r *http.Request) {
        challenge := r.URL.Query().Get("login_challenge")
        // 验证用户名/密码（业务逻辑自行实现）
        username := r.FormValue("username")

        // 4. 通知 Hydra 接受登录，传入内部用户 ID 作为 subject
        resp, _, err := adminAPI.OAuth2API.
            AcceptOAuth2LoginRequest(context.Background()).
            LoginChallenge(challenge).
            AcceptOAuth2LoginRequest(hydra.AcceptOAuth2LoginRequest{
                Subject:     username,
                Remember:    hydra.PtrBool(true),
                RememberFor: hydra.PtrInt64(3600),
            }).Execute()
        if err != nil {
            http.Error(w, err.Error(), http.StatusInternalServerError)
            return
        }
        // 5. 重定向回 Hydra 继续授权流程
        http.Redirect(w, r, resp.GetRedirectTo(), http.StatusFound)
    })

    fmt.Println("Login Provider 运行在 http://localhost:3000")
    http.ListenAndServe(":3000", nil)
}
</code></pre>

库名 核心特点 易用性 适用场景 coreos/go-oidc Go 生态最主流 OIDC 客户端，配合 <code>golang.org/x/oauth2</code> 使用，支持 Discovery 自动配置、JWKS 缓存和 ID Token 验证 ⭐⭐⭐⭐⭐ 服务端接入任意 OIDC 提供商 zitadel/oidc 现代化 OIDC 库，同时支持客户端与服务端，API 更简洁，类型安全，积极维护 ⭐⭐⭐⭐ 需同时实现客户端和服务端场景 <p>示例（coreos/go-oidc v3 接入 Google 并验证 ID Token）：</p> <pre><code>package main

import (
    "context"
    "fmt"
    "log"

    "github.com/coreos/go-oidc/v3/oidc"
    "golang.org/x/oauth2"
)

func main() {
    ctx := context.Background()

    // 通过 Discovery 端点自动获取 Provider 配置（含 JWKS URI）
    provider, err := oidc.NewProvider(ctx, "https://accounts.google.com")
    if err != nil {
        log.Fatal(err)
    }

    oauth2Config := &amp;oauth2.Config{
        ClientID:     "YOUR_CLIENT_ID",
        ClientSecret: "YOUR_CLIENT_SECRET",
        RedirectURL:  "http://localhost:8080/callback",
        Endpoint:     provider.Endpoint(),
        Scopes:       []string{oidc.ScopeOpenID, "email", "profile"},
    }

    // 生成授权 URL
    authURL := oauth2Config.AuthCodeURL("random-state")
    fmt.Println("请访问:", authURL)

    // 用授权码换取 Token
    token, err := oauth2Config.Exchange(ctx, "AUTHORIZATION_CODE")
    if err != nil {
        log.Fatal(err)
    }

    // 从 Token 中提取并验证 ID Token（签名、iss、aud、exp）
    verifier := provider.Verifier(&amp;oidc.Config{ClientID: "YOUR_CLIENT_ID"})
    rawIDToken, _ := token.Extra("id_token").(string)
    idToken, err := verifier.Verify(ctx, rawIDToken)
    if err != nil {
        log.Fatal("ID Token 验证失败:", err)
    }

    var claims struct {
        Email string `json:"email"`
        Name  string `json:"name"`
    }
    if err := idToken.Claims(&amp;claims); err != nil {
        log.Fatal(err)
    }
    fmt.Printf("用户: %s (%s)\n", claims.Name, claims.Email)
}
</code></pre>

库名 核心特点 易用性 支持的提供商 golang.org/x/oauth2 Go 官方 OAuth2 库，基础实现，需适配具体提供商，但生态丰富 ⭐⭐⭐⭐ 所有标准 OAuth2/OIDC 提供商 go-oauth2/oauth2 第三方增强版 OAuth2 库，支持多提供商、存储扩展，开箱即用 ⭐⭐⭐⭐⭐ Google、GitHub、Microsoft 等（内置适配） gin-contrib/oauth2 Gin 框架专属 OAuth2 扩展，封装官方库，快速集成 ⭐⭐⭐⭐⭐ Web 框架集成场景 <p>示例（go-oauth2/oauth2 对接 GitHub 登录）：</p> <pre><code>package main

import (
    "fmt"
    "net/http"

    "github.com/go-oauth2/oauth2/v4/errors"
    "github.com/go-oauth2/oauth2/v4/manage"
    "github.com/go-oauth2/oauth2/v4/models"
    "github.com/go-oauth2/oauth2/v4/server"
    "github.com/go-oauth2/oauth2/v4/store"
    "github.com/go-oauth2/github"
)

func main() {
    manager := manage.NewDefaultManager()
    // 内存存储客户端信息
    clientStore := store.NewClientStore()
    clientStore.Set("YOUR_CLIENT_ID", &amp;models.Client{
        ID:     "YOUR_CLIENT_ID",
        Secret: "YOUR_CLIENT_SECRET",
        Domain: "http://localhost:8080",
    })
    manager.MapClientStorage(clientStore)

    // 配置 GitHub 提供商
    githubProvider := github.NewProvider(
        "github.com/go-oauth2/github",
        "YOUR_CLIENT_ID",
        "YOUR_CLIENT_SECRET",
    )
    manager.MapProvider(githubProvider)

    srv := server.NewDefaultServer(manager)
    srv.SetAllowGetAccessRequest(true)
    srv.SetClientInfoHandler(server.ClientFormHandler)

    srv.SetInternalErrorHandler(func(err error) (re *errors.Response) {
        fmt.Println("Internal Error:", err.Error())
        return
    })

    srv.SetResponseErrorHandler(func(re *errors.Response) {
        fmt.Println("Response Error:", re.Error.Error())
    })

    // 登录入口
    http.HandleFunc("/login/github", func(w http.ResponseWriter, r *http.Request) {
        redirectURI := "http://localhost:8080/callback/github"
        authURL, err := githubProvider.GetAuthURL(r.Context(), redirectURI)
        if err != nil {
            http.Error(w, err.Error(), http.StatusInternalServerError)
            return
        }
        http.Redirect(w, r, authURL, http.StatusFound)
    })

    // 回调处理
    http.HandleFunc("/callback/github", func(w http.ResponseWriter, r *http.Request) {
        token, err := githubProvider.GetToken(r.Context(), r.URL.Query())
        if err != nil {
            http.Error(w, err.Error(), http.StatusInternalServerError)
            return
        }
        w.Write([]byte(fmt.Sprintf("Access Token: %s", token.AccessToken)))
    })

    fmt.Println("Server running on http://localhost:8080")
    http.ListenAndServe(":8080", nil)
}
</code></pre>

库名 核心特点 易用性 适用场景 openidconnect Rust 最主流 OIDC 客户端，基于 <code>oauth2-rs</code>，类型安全，支持 Discovery、PKCE、JWKS 签名验证 ⭐⭐⭐⭐ 类型安全的 OIDC 客户端开发 oidc 轻量 OIDC 客户端封装，内置 Discovery 和 Token 验证，API 比 openidconnect 更简洁 ⭐⭐⭐ 快速接入单一 OIDC 提供商的场景 <p>示例（openidconnect 使用 PKCE 授权码流程并验证 ID Token）：</p> <pre><code>use openidconnect::{
    core::{CoreClient, CoreProviderMetadata, CoreResponseType},
    AuthenticationFlow, AuthorizationCode, ClientId, ClientSecret,
    CsrfToken, IssuerUrl, Nonce, PkceCodeChallenge, RedirectUrl,
    Scope, TokenResponse,
};
use openidconnect::reqwest::async_http_client;

#[tokio::main]
async fn main() -&gt; Result&lt;(), Box&lt;dyn std::error::Error&gt;&gt; {
    // 通过 Discovery 端点自动配置 Provider（含 JWKS URI）
    let provider_metadata = CoreProviderMetadata::discover_async(
        IssuerUrl::new("https://accounts.google.com".to_string())?,
        async_http_client,
    )
    .await?;

    let client = CoreClient::from_provider_metadata(
        provider_metadata,
        ClientId::new("YOUR_CLIENT_ID".to_string()),
        Some(ClientSecret::new("YOUR_CLIENT_SECRET".to_string())),
    )
    .set_redirect_uri(RedirectUrl::new(
        "http://localhost:8080/callback".to_string(),
    )?);

    // 生成 PKCE 挑战码 + 授权 URL
    let (pkce_challenge, pkce_verifier) = PkceCodeChallenge::new_random_sha256();
    let (auth_url, _csrf_token, nonce) = client
        .authorize_url(
            AuthenticationFlow::&lt;CoreResponseType&gt;::AuthorizationCode,
            CsrfToken::new_random,
            Nonce::new_random,
        )
        .add_scope(Scope::new("email".to_string()))
        .set_pkce_challenge(pkce_challenge)
        .url();
    println!("请访问: {}", auth_url);

    // 用授权码 + PKCE 验证码换取 Token
    let token_response = client
        .exchange_code(AuthorizationCode::new("AUTHORIZATION_CODE".to_string()))
        .set_pkce_verifier(pkce_verifier)
        .request_async(async_http_client)
        .await?;

    // 验证 ID Token（签名、nonce、iss、aud、exp）
    let id_token = token_response.id_token().expect("未返回 ID Token");
    let claims = id_token.claims(&amp;client.id_token_verifier(), &amp;nonce)?;
    println!("用户 sub: {}", claims.subject().as_str());
    if let Some(email) = claims.email() {
        println!("Email: {}", email.as_str());
    }
    Ok(())
}
</code></pre>

