c.borrow_mut().push(4);  // 运行时检查

// 组合：Rc&lt;RefCell&lt;T&gt;&gt;
let rc_ref = Rc::new(RefCell::new(vec![1]));
rc_ref.borrow_mut().push(2);
</code></pre> <p>组合用法：</p> <ul> <li>单线程共享可变：<code>Rc&lt;RefCell&lt;T&gt;&gt;</code></li> <li>多线程共享可变：<code>Arc&lt;Mutex&lt;T&gt;&gt;</code></li> </ul>

组件 作用 场景 <code>Arc&lt;T&gt;</code> 原子引用计数 多线程共享配置、客户端 <code>Mutex&lt;T&gt;</code> 互斥写，同一时刻一个线程访问 需要独占访问，如：状态机、计数器 <code>RwLock&lt;T&gt;</code> 读写锁，多读单写 配置快照、路由表 <p>示例1：</p> <pre><code>use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let counter = Arc::new(Mutex::new(0_i64));
    let mut handles = Vec::new();

    for _ in 0..8 {
        let c = Arc::clone(&amp;counter);
        handles.push(thread::spawn(move || {
            let mut n = c.lock().expect("lock poisoned");
            *n += 1;
        }));
    }

    for h in handles {
        h.join().expect("join failed");
    }

    println!("count={}", *counter.lock().expect("lock poisoned"));
}
</code></pre> <p>示例2：</p> <pre><code>use std::sync::{Mutex, RwLock};

let mutex = Mutex::new(0);
{
    let mut num = mutex.lock().unwrap();
    *num = 5;
}  // lock自动释放

let rwlock = RwLock::new(vec![1, 2, 3]);

// 读操作（可多个同时）
{
    let r1 = rwlock.read().unwrap();
    let r2 = rwlock.read().unwrap();
}

// 写操作（独占）
{
    let mut w = rwlock.write().unwrap();
    w.push(4);
}
</code></pre>

